<script lang="ts">
 import {onMount} from 'svelte';import Portrait from './Portrait.svelte';import MediaShelf from './MediaShelf.svelte';import {groupMedia} from './collection';import {groupCard,workCard,type Card} from './experience';import type {Entry,Work,Contributor} from './types';
 export let provider='';export let id='';export let name='';export let entries:Entry[];export let token:string;export let open:(c:Card)=>void;
 const localName=name;
 let image='';let imageSource='';let imageCredit='';let imageLicense='';let candidates:Contributor[]=[];
 let biography='';let detail='';let works:Work[]=[];let page=1;let pages=1;let busy=false;let error='';let alive=true;const abort=new AbortController();
 $: local=groupMedia(entries.filter(e=>e.kind==='music'&&[e.metadata?.artist,e.metadata?.albumArtist].some(a=>a?.toLocaleLowerCase()===localName.toLocaleLowerCase()))).map(groupCard);
 onMount(()=>{if(id)void load(1);else void explore();return()=>{alive=false;abort.abort();};});
 async function load(next:number){busy=true;error='';try{const r=await fetch(`/api/v1/people/${provider}/${encodeURIComponent(id)}?page=${next}`,{signal:abort.signal});const data=await r.json();if(!r.ok)throw new Error(data.error);if(alive){name=data.name;biography=data.biography;detail=data.detail;image=data.image||'';imageSource=data.imageSource||'';imageCredit=data.imageCredit||'';imageLicense=data.imageLicense||'';works=data.works;page=data.page;pages=data.pages;}}catch(e){if(alive)error=e instanceof Error?e.message:'Profil indisponible.';}finally{if(alive)busy=false;}}
 async function choose(person:Contributor){provider='musicbrainz';id=person.id;candidates=[];await load(1);}
 async function explore(){busy=true;error='';try{const r=await fetch('/api/v1/people/musicbrainz/resolve',{method:'POST',headers:{'Content-Type':'application/json','X-Mosaune-Token':token},body:JSON.stringify({name:localName}),signal:abort.signal});const data=await r.json();if(!r.ok)throw new Error(data.error);if(!alive)return;candidates=data;const exact=candidates.filter(p=>p.name.toLocaleLowerCase()===localName.toLocaleLowerCase());if(exact.length===1)await choose(exact[0]);}catch(e){if(alive)error=e instanceof Error?e.message:'Identification indisponible.';}finally{if(alive)busy=false;}}
</script>
<article class="person-page"><header class="person-hero"><div class="person-photo"><Portrait {name} {image} large/>{#if imageSource}<a class="photo-credit" href={imageSource} target="_blank" rel="noreferrer">Photo : {imageCredit||'Wikimedia Commons'}{imageLicense?` · ${imageLicense}`:''} ↗</a>{/if}</div><div><span class="eyebrow">{provider==='tmdb'?'DEVANT LA CAMÉRA':'DERRIÈRE LA MUSIQUE'}</span><h1>{name}</h1><p>{detail||'Une personne, plusieurs histoires.'}</p>{#if !id}<button class="secondary" disabled={busy} onclick={explore}>Identifier l’artiste sur MusicBrainz</button>{/if}</div></header>
{#if candidates.length}<section class="artist-candidates"><h2>De quel artiste s’agit-il ?</h2><p>Choisissez le bon profil pour éviter les homonymes.</p>{#each candidates as candidate}<button class="secondary" disabled={busy} onclick={()=>choose(candidate)}>{candidate.name} {candidate.role?`· ${candidate.role}`:''}</button>{/each}</section>{/if}
{#if biography}<section class="person-biography"><h2>À propos</h2><p>{biography}</p></section>{/if}
{#if busy}<p role="status" class="folder-help">Chargement des projets…</p>{/if}{#if error}<p class="notice" role="alert">{error}</p><button class="secondary" disabled={busy} onclick={()=>id?load(page):explore()}>Réessayer</button>{/if}
{#if local.length}<MediaShelf title="Dans votre collection" cards={local} {open}/>{/if}
{#if works.length}<MediaShelf title={provider==='tmdb'?'Filmographie':'Discographie et éditions'} subtitle={!id?'Recherche par nom : des homonymes sont possibles. Ouvrez un album pour vérifier les artistes crédités.':'Projets référencés par le fournisseur.'} cards={works.map(workCard)} {open} grid/>{:else if id&&!busy&&!error}<p>Aucun projet renseigné sur cette page.</p>{/if}
{#if id&&pages>1}<div class="discovery-pagination"><button class="secondary" disabled={busy||page<=1} onclick={()=>load(page-1)}>Précédent</button><span>{page} / {pages}</span><button class="secondary" disabled={busy||page>=pages} onclick={()=>load(page+1)}>Suivant</button></div>{/if}
</article>
